mapper.select:
SELECT o.id, o.order_no AS orderNo, o.warehouse_id AS warehouseId, w.name AS warehouseName, o.supplier, o.operator_id AS operatorId, u.real_name AS operatorName, o.total_amount AS totalAmount, o.status, o.remark, o.audit_time AS auditTime, o.auditor_id AS auditorId, o.create_time AS createTime, o.update_time AS updateTime FROM stock_in_order o LEFT JOIN warehouse w ON o.warehouse_id = w.id LEFT JOIN sys_user u ON o.operator_id = u.id
AND o.status = #{dto.status}
AND (o.order_no LIKE CONCAT('%', #{dto.keyword}, '%') OR o.supplier LIKE CONCAT('%', #{dto.keyword}, '%'))
ORDER BY o.create_time DESC LIMIT #{offset}, #{dto.pageSize}

SELECT COUNT(*) FROM stock_in_order o
AND o.status = #{dto.status}
AND (o.order_no LIKE CONCAT('%', #{dto.keyword}, '%') OR o.supplier LIKE CONCAT('%', #{dto.keyword}, '%'))
